@keyframes spin {
    to {
        transform: rotate(360deg)
    }
}
.animate-spin {
    animation: spin 1s linear infinite
}
@keyframes ping {
    75%, 100% {
        transform: scale(2);
        opacity: 0
    }
}
.hover\:animate-ping:hover {
    animation: ping 1s cubic-bezier(0, 0, 0.2, 1) infinite
}
@keyframes bounce {
    0%, 100% {
        transform: translateY(-25%);
        animation-timing-function: cubic-bezier(0.8,0,1,1)
    }
    50% {
        transform: none;
        animation-timing-function: cubic-bezier(0,0,0.2,1)
    }
}
.group:hover .group-hover\:animate-bounce {
    animation: bounce 1s infinite
}

@keyframes one {
    to {
        transform: rotate(360deg)
    }
}
.animate-one {
    animation: one 2s
}

@keyframes tw-one {
    to {
        transform: rotate(360deg)
    }
}
.tw-animate-one {
    animation: tw-one 2s
}

@keyframes bounce {
    0%, 100% {
        transform: translateY(-25%);
        animation-timing-function: cubic-bezier(0.8,0,1,1)
    }
    50% {
        transform: none;
        animation-timing-function: cubic-bezier(0,0,0.2,1)
    }
}
@keyframes pulse {
    50% {
        opacity: .5
    }
}
.animate-multiple {
    animation: bounce 2s linear, pulse 3s ease-in
}

@keyframes one {
    to {
        transform: rotate(360deg)
    }
}
@keyframes two {
    to {
        transform: scale(1.23)
    }
}
.animate-multiple {
    animation: one 2s, two 3s
}

@keyframes zoom-\.5 {
    to {
        transform: scale(0.5)
    }
}
.animate-zoom-\.5 {
    animation: zoom-\.5 2s
}
@keyframes zoom-1\.5 {
    to {
        transform: scale(1.5)
    }
}
.animate-zoom-1\.5 {
    animation: zoom-1\.5 2s
}

